-- The two words above a partner's mark, in four languages.
--
-- GENERATED BY, and not "in association with", which is what the feature
-- was first specified as. The difference is not stylistic. "In
-- association with" asserts a relationship between this site and the
-- partner, on a site whose entire value is that its judgements are its
-- own and traceable to primary sources. "Generated by" asserts only who
-- produced this copy of this file -- a fact, and one that stays true when
-- the PDF is forwarded to somebody who works somewhere else.
--
-- The same key in both namespaces because the two documents are rendered
-- by different modules with separate string bundles, and a shared key
-- across namespaces is not a thing this schema has. Two rows per language
-- is cheaper than the abstraction that would avoid them.
--
-- No {0}: the partner's name is in the logo underneath, and repeating it
-- in text above the wordmark reads as a caption on a caption.

INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'guides.doc.partnerBy', 'en', 'Generated by');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'guides.doc.partnerBy', 'es', 'Generado por');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'guides.doc.partnerBy', 'de', 'Erstellt von');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'guides.doc.partnerBy', 'fr', 'Généré par');

INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('roi', 'pdf.partnerBy', 'en', 'Generated by');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('roi', 'pdf.partnerBy', 'es', 'Generado por');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('roi', 'pdf.partnerBy', 'de', 'Erstellt von');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('roi', 'pdf.partnerBy', 'fr', 'Généré par');

